          "code": "def __init__(self, r: float, g: float, b: float, a: float, name: str = \"my_color\"):\n\n        self._guid = None\n        self.name = name\n        self._r = max(0.0, min(1.0, float(r)))\n        self._g = max(0.0, min(1.0, float(g)))\n        self._b = max(0.0, min(1.0, float(b)))\n        self._a = max(0.0, min(1.0, float(a)))\n\n    @property\n    def guid(self) -> str:\n        if getattr(self, '_guid', None) is None:\n            self._guid = str(uuid.uuid4())\n        return self._guid\n\n    @guid.setter\n    def guid(self, value: str):\n        self._guid = value\n\n    @property\n    def r(self):\n        return self._r\n\n    @r.setter\n    def r(self, value):\n        self._r = max(0.0, min(1.0, float(value)))\n\n    @property\n    def g(self):\n        return self._g\n\n    @g.setter\n    def g(self, value):\n        self._g = max(0.0, min(1.0, float(value)))\n\n    @property\n    def b(self):\n        return self._b\n\n    @b.setter\n    def b(self, value):\n        self._b = max(0.0, min(1.0, float(value)))\n\n    @property\n    def a(self):\n        return self._a\n\n    @a.setter\n    def a(self, value):\n        self._a = max(0.0, min(1.0, float(value)))\n\n    ###########################################################################################\n    # Operators\n    ###########################################################################################\n\n    def __deepcopy__(self, memo):\n\n        cls = self.__class__\n        result = cls.__new__(cls)\n        memo[id(self)] = result\n\n        # New guid\n        result.guid = str(uuid.uuid4())\n\n        # Copy remaining fields\n        result.name = copy.deepcopy(self.name, memo)\n        result._r = self._r\n        result._g = self._g\n        result._b = self._b\n        result._a = self._a\n        return result\n\n    def duplicate(self) -> \"Color\":\n        \"\"\"Create a deep copy of this color with a new GUID.\n\n        Returns\n        -------\n        :class:`Color`\n            A new Color with identical RGBA values but a different GUID.\n\n        \"\"\"",
