          "code": "def add_feature(self, feature):\n\n        self._features.append(feature)\n        self._is_dirty = True\n\n    def set_geometry(self, geometry):\n        self._geometry = geometry\n        self._is_dirty = True\n\n    def set_polylines(self, polylines):\n        self._polylines = polylines\n\n    def set_planes(self, planes):\n        self._planes = planes\n\n    def reset(self):\n        self._is_dirty = True\n        self._aabb = None\n        self._obb = None\n        self._collision_mesh = None\n        self._point = None\n        self._polylines = None\n        self._planes = None\n        self._edge_vectors = None\n        self._axis = None\n\n    ###########################################################################################\n    # Computation\n    ###########################################################################################\n\n    def compute_aabb(self):\n        from .obb import OBB\n        from .point import Point\n        geo = self.session_geometry\n        if geo is None:\n            return OBB.from_point(Point(0, 0, 0), 0.0)\n        return self._obb_from_geometry(geo, aabb=True)\n\n    def compute_obb(self):\n        from .obb import OBB\n        from .point import Point\n        geo = self.session_geometry\n        if geo is None:\n            return OBB.from_point(Point(0, 0, 0), 0.0)\n        return self._obb_from_geometry(geo, aabb=False)\n\n    def compute_collision_mesh(self):\n        from .mesh import Mesh\n        geo = self.session_geometry\n        if geo is None:\n            return Mesh()\n        if isinstance(geo, Mesh):\n            return geo\n        return Mesh()\n\n    def compute_point(self):\n        from .point import Point\n        from .mesh import Mesh\n        from .brep import BRep\n        geo = self.session_geometry\n        if geo is None:\n            return Point(0, 0, 0)\n        if isinstance(geo, Mesh):\n            verts = list(geo.vertex.values())\n            if not verts:\n                return Point(0, 0, 0)\n            sx = sum(v.x for v in verts)\n            sy = sum(v.y for v in verts)\n            sz = sum(v.z for v in verts)\n            n = len(verts)\n            return Point(sx / n, sy / n, sz / n)\n        if isinstance(geo, BRep):\n            pts = geo.m_vertices\n            if not pts:\n                return Point(0, 0, 0)\n            sx = sum(p[0] for p in pts)\n            sy = sum(p[1] for p in pts)\n            sz = sum(p[2] for p in pts)\n            n = len(pts)\n            return Point(sx / n, sy / n, sz / n)\n        return Point(0, 0, 0)",
