          "code": "std::string Element::pb_dumps() const {\n    session_proto::Element proto;\n    proto.set_guid(guid());\n    proto.set_name(name);\n    if (auto* mesh = std::get_if<Mesh>(&_geometry)) {\n        proto.set_geometry_type(\"Mesh\");\n        proto.set_geometry_data(mesh->pb_dumps());\n    }",
