          "code": "def pb_dump(self, filepath):\n\n        with open(filepath, 'wb') as f:\n            f.write(self.pb_dumps())\n\n    @classmethod\n    def pb_load(cls, filepath):\n        with open(filepath, 'rb') as f:\n            return cls.pb_loads(f.read())\n\n    ###########################################################################################\n    # Details: Essential Graph Methods\n    ###########################################################################################\n\n    def has_node(self, key):\n        \"\"\"Check if a node exists in the graph.\n\n        Parameters\n        ----------\n        key : str\n            The node to check for.\n\n        Returns\n        -------\n        bool\n            True if the node exists.\n\n        Examples\n        --------\n        >>> graph = Graph()\n        >>> graph.add_node(\"node1\")\n        'node1'\n        >>> graph.has_node(\"node1\")\n        True\n        >>> graph.has_node(\"node2\")\n        False\n        \"\"\"\n        return key in self.vertices\n\n    def has_edge(self, edge):\n        \"\"\"Check if an edge exists in the graph.\n\n        Parameters\n        ----------\n        edge : tuple or str\n            Either a tuple (u, v) or two separate arguments u, v.\n\n        Returns\n        -------\n        bool\n            True if the edge exists, False otherwise.\n\n        Examples\n        --------\n        >>> graph = Graph()\n        >>> graph.add_edge(\"A\", \"B\", \"edge_attr\")\n        ('A', 'B')\n        >>> graph.has_edge((\"A\", \"B\"))\n        True\n        >>> graph.has_edge((\"C\", \"D\"))\n        False\n        \"\"\"\n        if isinstance(edge, tuple):\n            u, v = edge\n        else:\n            raise ValueError(\"Edge must be a tuple (u, v)\")\n\n        return u in self.edges and v in self.edges[u]\n\n    def add_node(self, key, attribute=\"\"):\n        \"\"\"Add a node to the graph.\n\n        Parameters\n        ----------\n        key : str\n            The node identifier.\n        attribute : str, optional\n            Node attribute data.\n\n        Returns\n        -------",
