          "code": "pub fn svd(&self) -> (Matrix, Vec<f32>, Matrix) {\n        let (m, n) = (self.rows, self.cols);\n        let at = self.transpose();\n        let ata = at.multiply(self);\n        let mut pairs = ata.eigen_decompose_symmetric();\n        pairs.sort_by(|a, b| b.0.partial_cmp(&a.0).unwrap_or(std::cmp::Ordering::Equal));\n        let k = m.min(n);\n        let mut singular_values = Vec::with_capacity(k);\n        let mut v_cols: Vec<Vec<f32>> = Vec::with_capacity(k);\n        for i in 0..k {\n            let (ev, evec) = &pairs[i];\n            singular_values.push(ev.max(0.0).sqrt());\n            v_cols.push(evec.clone());\n        }\n        let mut v = Self::zeros(n, k);\n        for j in 0..k {\n            for i in 0..n {\n                v[(i, j)] = v_cols[j][i];\n            }\n        }\n        let mut u = Self::zeros(m, k);\n        for j in 0..k {\n            if singular_values[j] > 1e-12 {\n                for i in 0..m {\n                    let val: f32 = (0..n).map(|l| self[(i, l)] * v[(l, j)]).sum();\n                    u[(i, j)] = val / singular_values[j];\n                }\n            }\n        }\n        let vt = v.transpose();\n        (u, singular_values, vt)\n    }",
