          "code": "bool NurbsCurve::insert_nurbsknot(double nurbsknot_value, int nurbsknot_multiplicity) {\n    if (!is_valid()) return false;\n\n    int p = degree();\n    if (nurbsknot_multiplicity < 1 || nurbsknot_multiplicity > p) {\n        return false;\n    }",
