          "code": "double NurbsCurve::greville_abcissa(int cv_index) const {\n    if (cv_index < 0 || cv_index >= m_cv_count) return 0.0;\n\n    const double* nurbsknot = m_nurbsknot.data() + cv_index;\n    int order = m_order;\n\n    if (order <= 2 || nurbsknot[0] == nurbsknot[order - 2]) {\n        return nurbsknot[0];\n    }",
