          "code": "pub fn point_at_corner(&self, u_end: usize, v_end: usize) -> Option<Point> {\n        let (u0, u1) = self.domain(0)?;\n        let (v0, v1) = self.domain(1)?;\n\n        let u = if u_end == 0 { u0 } else { u1 };\n        let v = if v_end == 0 { v0 } else { v1 };\n\n        self.point_at(u, v)\n    }",
