        "cpp": {
          "sig": "OBB pb_loads(const std::string& data)",
          "code": "OBB OBB::pb_loads(const std::string& data) {\n    session_proto::BoundingBox proto;\n    proto.ParseFromString(data);\n    Point c = Point::pb_loads(proto.center().SerializeAsString());\n    Vector xa = Vector::pb_loads(proto.x_axis().SerializeAsString());\n    Vector ya = Vector::pb_loads(proto.y_axis().SerializeAsString());\n    Vector za = Vector::pb_loads(proto.z_axis().SerializeAsString());\n    Vector hs = Vector::pb_loads(proto.half_size().SerializeAsString());\n    OBB box(c, xa, ya, za, hs);\n    box.guid() = proto.guid();\n    box.name = proto.name();\n    if (proto.has_xform()) {\n        box.xform = Xform::pb_loads(proto.xform().SerializeAsString());\n    }",
          "file": "obb.cpp"
        },
        "rust": {
          "sig": "pb_loads(data: &[u8]) -> Result<Self, Box<dyn std::error::Error>>",
          "code": "pub fn pb_loads(data: &[u8]) -> Result<Self, Box<dyn std::error::Error>> {\n        use prost::Message;\n        let proto = crate::proto::BoundingBox::decode(data)?;\n        let center = if let Some(p) = &proto.center {\n            crate::point::Point::pb_loads(&p.encode_to_vec())?\n        } else {\n            crate::point::Point::new(0.0, 0.0, 0.0)\n        };\n        let x_axis = if let Some(v) = &proto.x_axis {\n            crate::vector::Vector::pb_loads(&v.encode_to_vec())?\n        } else {\n            crate::vector::Vector::new(1.0, 0.0, 0.0)\n        };\n        let y_axis = if let Some(v) = &proto.y_axis {\n            crate::vector::Vector::pb_loads(&v.encode_to_vec())?\n        } else {\n            crate::vector::Vector::new(0.0, 1.0, 0.0)\n        };\n        let z_axis = if let Some(v) = &proto.z_axis {\n            crate::vector::Vector::pb_loads(&v.encode_to_vec())?\n        } else {\n            crate::vector::Vector::new(0.0, 0.0, 1.0)\n        };\n        let half_size = if let Some(v) = &proto.half_size {\n            crate::vector::Vector::pb_loads(&v.encode_to_vec())?\n        } else {\n            crate::vector::Vector::new(0.5, 0.5, 0.5)\n        };\n        let mut bbox = OBB::new(center, x_axis, y_axis, z_axis, half_size);\n        bbox.set_guid(proto.guid);\n        bbox.name = proto.name;\n        if let Some(xform) = proto.xform {\n            bbox.xform.set_guid(xform.guid);\n            bbox.xform.name = xform.name;\n            for (i, val) in xform.matrix.iter().enumerate() {\n                if i < 16 { bbox.xform.m[i] = *val as f32; }\n            }\n        }\n        Ok(bbox)\n    }",
          "file": "obb.rs"
        }
