          "code": "def file_json_dump(self, filepath) -> None:\n\n        \"\"\"Write JSON to file.\"\"\"\n        import json\n        with open(filepath, 'w') as f:\n            json.dump(self.__jsondump__(), f, indent=2)\n\n    @classmethod\n    def file_json_load(cls, filepath) -> \"PointCloud\":\n        \"\"\"Read JSON from file.\"\"\"\n        import json\n        with open(filepath, 'r') as f:\n            data = json.load(f)\n        return cls.__jsonload__(data)\n\n    def file_json_dumps(self):\n        \"\"\"Convert to JSON string.\"\"\"\n        import json\n        return json.dumps(self.__jsondump__())\n\n    @classmethod\n    def file_json_loads(cls, json_string):\n        \"\"\"Load from JSON string.\"\"\"\n        import json\n        return cls.__jsonload__(json.loads(json_string))\n\n    ###########################################################################################\n    # Protobuf Serialization\n    ###########################################################################################\n\n    def pb_dumps(self) -> bytes:\n        \"\"\"Convert to protobuf binary format.\"\"\"\n        from .proto import pointcloud_pb2\n\n        proto = pointcloud_pb2.PointCloud()\n        proto.guid = self.guid\n        proto.name = self.name\n        proto.coords.extend(self.coords)\n        proto.colors.extend([int(round(v * 255)) for v in self._colors])\n        proto.normals.extend(self._normals)\n        proto.point_size = self.point_size\n\n        # Serialize xform\n        proto.xform.name = self.xform.name\n        proto.xform.matrix.extend(self.xform.m)\n\n        return proto.SerializeToString()\n\n    @classmethod\n    def pb_loads(cls, data: bytes) -> \"PointCloud\":\n        \"\"\"Create from protobuf binary format.\"\"\"\n        from .proto import pointcloud_pb2\n\n        proto = pointcloud_pb2.PointCloud()\n        proto.ParseFromString(data)\n\n        pc = cls.from_coords(\n            list(proto.coords),\n            [v / 255.0 for v in proto.colors],\n            list(proto.normals)\n        )\n        pc.guid = proto.guid\n        pc.name = proto.name\n        pc.point_size = proto.point_size if proto.point_size > 0 else 1.0\n\n        # Deserialize xform\n        if proto.HasField(\"xform\"):\n            pc.xform.name = proto.xform.name\n            for i, val in enumerate(proto.xform.matrix):\n                if i < 16:\n                    pc.xform.m[i] = val\n\n        return pc\n\n    def pb_dump(self, filepath) -> None:\n        \"\"\"Write protobuf to file.\"\"\"\n        with open(filepath, 'wb') as f:\n            f.write(self.pb_dumps())\n\n    @classmethod\n    def pb_load(cls, filepath) -> \"PointCloud\":",
