          "sig": "__init__(x=0, y=0)",
          "code": "def __init__(self, x=0, y=0):\n\n        self.x = int(x)\n        self.y = int(y)\n\n    def __eq__(self, o):\n        return self.x == o.x and self.y == o.y\n\n    def __ne__(self, o):\n        return not self.__eq__(o)\n\n    def __hash__(self):\n        return hash((self.x, self.y))\n\n\nclass _V2:\n    __slots__ = ('pt', 'edges', 'innerLM')\n\n    def __init__(self, pt):\n        self.pt = pt\n        self.edges = []\n        self.innerLM = False\n\n\nclass _Edge:\n    __slots__ = ('vL', 'vR', 'vB', 'vT', 'kind', 'triA', 'triB', 'isActive', 'nextE', 'prevE')\n\n    def __init__(self):\n        self.vL = self.vR = self.vB = self.vT = None\n        self.kind = _LOOSE\n        self.triA = self.triB = None\n        self.isActive = False\n        self.nextE = self.prevE = None\n\n\nclass _Tri:\n    __slots__ = ('edges',)\n\n    def __init__(self, e1, e2, e3):\n        self.edges = [e1, e2, e3]\n\n\ndef _cps(p1, p2, p3):\n    cp = (p2.x - p1.x) * (p3.y - p2.y) - (p2.y - p1.y) * (p3.x - p2.x)\n    return 1 if cp > 0 else (-1 if cp < 0 else 0)\n\n\ndef _sqr(x):\n    return x * x\n\n\ndef _dist_sqr(a, b):\n    dx = a.x - b.x\n    dy = a.y - b.y\n    return dx * dx + dy * dy\n\n\ndef _left_turning(p1, p2, p3):\n    cp = (p2.x - p1.x) * (p3.y - p2.y) - (p2.y - p1.y) * (p3.x - p2.x)\n    return cp < 0\n\n\ndef _right_turning(p1, p2, p3):\n    cp = (p2.x - p1.x) * (p3.y - p2.y) - (p2.y - p1.y) * (p3.x - p2.x)\n    return cp > 0\n\n\ndef _is_horiz(e):\n    return e.vB.pt.y == e.vT.pt.y\n\n\ndef _is_loose(e):\n    return e.kind == _LOOSE\n\n\ndef _is_left_edge(e):\n    return e.kind == _ASCEND\n\n\ndef _is_right_edge(e):\n    return e.kind == _DESCEND",
