          "code": "Mesh RemeshCDT::from_polylines(const std::vector<Polyline>& polylines, bool is_2d, bool is_first_boundary) {\n    if (polylines.empty()) return Mesh();\n\n    // Find border index\n    int border_idx = 0;\n    if (!is_first_boundary && polylines.size() > 1) {\n        double max_diag = 0.0;\n        for (size_t i = 0; i < polylines.size(); ++i) {\n            auto pts = polylines[i].get_points();\n            if (pts.size() < 3) continue;\n            double minx = pts[0][0], miny = pts[0][1], minz = pts[0][2];\n            double maxx = minx, maxy = miny, maxz = minz;\n            for (const auto& p : pts) {\n                if (p[0] < minx) minx = p[0]; if (p[0] > maxx) maxx = p[0];\n                if (p[1] < miny) miny = p[1]; if (p[1] > maxy) maxy = p[1];\n                if (p[2] < minz) minz = p[2]; if (p[2] > maxz) maxz = p[2];\n            }",
