          "code": "pub fn add<'a>(&mut self, node: &Rc<RefCell<TreeNode>>, parent: impl Into<Option<&'a Rc<RefCell<TreeNode>>>>)\n    where\n        Rc<RefCell<TreeNode>>: 'a,\n    {\n        let parent_opt = parent.into();\n        if parent_opt.is_none() {\n            if let Some(root) = self.tree.root() {\n                self.tree.add(node, Some(&root));\n            }\n        } else {\n            self.tree.add(node, parent_opt);\n        }\n    }",
