          "code": "def plane_to_xy(origin, x_axis, y_axis, z_axis):\n\n        x = x_axis.normalized()\n        y = y_axis.normalized()\n        z = z_axis.normalized()\n        t = Xform.translation(-origin[0], -origin[1], -origin[2])\n        f = Xform()\n        f.m[0] = x[0]\n        f.m[1] = x[1]\n        f.m[2] = x[2]\n        f.m[4] = y[0]\n        f.m[5] = y[1]\n        f.m[6] = y[2]\n        f.m[8] = z[0]\n        f.m[9] = z[1]\n        f.m[10] = z[2]\n        return f * t\n\n    @staticmethod\n    def xy_to_plane(origin, x_axis, y_axis, z_axis):\n        x = x_axis.normalized()\n        y = y_axis.normalized()\n        z = z_axis.normalized()\n        f = Xform()\n        f.m[0] = x[0]\n        f.m[4] = y[0]\n        f.m[8] = z[0]\n        f.m[1] = x[1]\n        f.m[5] = y[1]\n        f.m[9] = z[1]\n        f.m[2] = x[2]\n        f.m[6] = y[2]\n        f.m[10] = z[2]\n        t = Xform.translation(origin[0], origin[1], origin[2])\n        return t * f\n\n    @staticmethod\n    def world_to_frame(origin, x_axis, y_axis, z_axis):\n        # Correct world\u00e2\u2020\u2019local rotation + translation. Stores basis as matrix\n        # ROWS \u00e2\u20ac\u201d for world point p the result is f*(p - origin) where f is the\n        # rotation whose rows are the unit basis vectors. Unlike plane_to_xy\n        # (which stores basis as columns and is actually local-to-world),\n        # world_to_frame is a faithful 3D projection \u00e2\u20ac\u201d needed when the input\n        # geometry's normal aligns with one of the basis axes. See\n        # wood_main.cpp type-13 branch.\n        x = x_axis.normalized()\n        y = y_axis.normalized()\n        z = z_axis.normalized()\n        f = Xform()\n        f.m[0] = x[0]; f.m[4] = x[1]; f.m[8]  = x[2]\n        f.m[1] = y[0]; f.m[5] = y[1]; f.m[9]  = y[2]\n        f.m[2] = z[0]; f.m[6] = z[1]; f.m[10] = z[2]\n        t = Xform.translation(-origin[0], -origin[1], -origin[2])\n        return f * t\n\n    @staticmethod\n    def frame_to_world(origin, x_axis, y_axis, z_axis):\n        # Inverse of world_to_frame: local (u, v, w) -> world point at\n        # origin + u*x_hat + v*y_hat + w*z_hat. Stores basis as matrix COLUMNS.\n        x = x_axis.normalized()\n        y = y_axis.normalized()\n        z = z_axis.normalized()\n        f = Xform()\n        f.m[0] = x[0]; f.m[1] = x[1]; f.m[2]  = x[2]\n        f.m[4] = y[0]; f.m[5] = y[1]; f.m[6]  = y[2]\n        f.m[8] = z[0]; f.m[9] = z[1]; f.m[10] = z[2]\n        t = Xform.translation(origin[0], origin[1], origin[2])\n        return t * f\n\n    @staticmethod\n    def to_frame(frame):\n        \"\"\"Transform from world XY to target frame/plane (same as COMPAS from_frame).\n\n        Parameters\n        ----------\n        frame : Plane\n            Target frame/plane.\n\n        Returns\n        -------\n        :class:`Xform`",
