      "name": "ElementPlate.polygon_normal",
      "implementations": {
        "cpp": {
          "sig": "Vector polygon_normal(const std::vector<Point>& pts)",
          "code": "Vector ElementPlate::polygon_normal(const std::vector<Point>& pts) {\n    double nx = 0, ny = 0, nz = 0;\n    size_t n = pts.size();\n    for (size_t i = 0; i < n; ++i) {\n        const auto& c = pts[i];\n        const auto& nx_pt = pts[(i + 1) % n];\n        nx += (c[1] - nx_pt[1]) * (c[2] + nx_pt[2]);\n        ny += (c[2] - nx_pt[2]) * (c[0] + nx_pt[0]);\n        nz += (c[0] - nx_pt[0]) * (c[1] + nx_pt[1]);\n    }",
          "file": "element.cpp"
        }
      },
