      "name": "Matrix.repr",
      "implementations": {
        "cpp": {
          "sig": "std::string repr()",
          "code": "std::string Matrix::repr() const {\n    std::string gp = guid().size() >= 8 ? guid().substr(0, 8) : guid();\n    std::ostringstream oss;\n    oss << \"Matrix(name='\" << name << \"', guid='\" << gp << \"...', rows=\" << rows << \", cols=\" << cols << \", data=[\";\n    for (int i = 0; i < rows; ++i) {\n        if (i > 0) oss << \"; \";\n        oss << \"[\";\n        for (int j = 0; j < cols; ++j) {\n            if (j > 0) oss << \", \";\n            oss << std::fixed << (*this)(i, j);\n        }",
          "file": "matrix.cpp"
        },
        "rust": {
          "sig": "repr() -> String",
          "code": "pub fn repr(&self) -> String {\n        let guid_str = self.guid();\n        let guid_prefix = &guid_str[..8.min(guid_str.len())];\n        let rows_str: Vec<String> = (0..self.rows)\n            .map(|i| {\n                let row: Vec<String> = (0..self.cols)\n                    .map(|j| format!(\"{:.6}\", self[(i, j)]))\n                    .collect();\n                format!(\"[{}]\", row.join(\", \"))\n            })\n            .collect();\n        format!(\n            \"Matrix(name='{}', guid='{}...', rows={}, cols={}, data=[{}])\",\n            self.name, guid_prefix, self.rows, self.cols, rows_str.join(\"; \")\n        )\n    }",
          "file": "matrix.rs"
        }
      },
