          "code": "void NurbsCurve::basis_functions_derivatives(int span, double t, int deriv_order,\n                                            std::vector<std::vector<double>>& ders) const {\n    int p = degree();\n    int n_der = std::min(deriv_order, p);\n\n    ders.assign(n_der + 1, std::vector<double>(p + 1, 0.0));\n\n    std::vector<double> left(p + 1);\n    std::vector<double> right(p + 1);\n    std::vector<std::vector<double>> ndu(p + 1, std::vector<double>(p + 1, 0.0));\n\n    // Use same nurbsknot offset as basis_functions\n    const double* nurbsknot = m_nurbsknot.data() + (m_order - 2) + span;\n\n    ndu[0][0] = 1.0;\n    for (int j = 1; j <= p; ++j) {\n        left[j] = t - nurbsknot[1 - j];\n        right[j] = nurbsknot[j] - t;\n        double saved = 0.0;\n        for (int r = 0; r < j; ++r) {\n            ndu[j][r] = right[r + 1] + left[j - r];  // Store nurbsknot differences\n            double temp = ndu[r][j - 1] / ndu[j][r];\n            ndu[r][j] = saved + right[r + 1] * temp;\n            saved = left[j - r] * temp;\n        }",
