      "implementations": {
        "cpp": {
          "sig": "double simplify_perp_dist(const Point& pt, const Point& line_start, const Point& line_end)",
          "code": "double Polyline::simplify_perp_dist(const Point& pt, const Point& line_start, const Point& line_end) {\n    double dx = line_end[0] - line_start[0];\n    double dy = line_end[1] - line_start[1];\n    double dz = line_end[2] - line_start[2];\n    double len_sq = dx * dx + dy * dy + dz * dz;\n    if (len_sq == 0.0) {\n        double ex = pt[0] - line_start[0];\n        double ey = pt[1] - line_start[1];\n        double ez = pt[2] - line_start[2];\n        return std::sqrt(ex * ex + ey * ey + ez * ez);\n    }",
          "file": "polyline.cpp"
        }
      },
