      "implementations": {
        "cpp": {
          "sig": "void radius_rec(const Node* node, const std::vector<Point>& pts, const Point& q, double r2, std::vector<std::pair<int, double>>& result)",
          "code": "void SpatialKDTree::radius_rec(const Node* node, const std::vector<Point>& pts, const Point& q, double r2, std::vector<std::pair<int, double>>& result) {\n    if (!node) return;\n    double d = dist_sq(q, pts[node->idx]);\n    if (d <= r2) result.emplace_back(node->idx, std::sqrt(d));\n    double diff = q[node->axis] - pts[node->idx][node->axis];\n    const Node* near = (diff <= 0) ? node->left.get() : node->right.get();\n    const Node* far  = (diff <= 0) ? node->right.get() : node->left.get();\n    radius_rec(near, pts, q, r2, result);\n    if (diff * diff <= r2) radius_rec(far, pts, q, r2, result);\n}",
          "file": "spatial_kdtree.cpp"
        }
      },
