          "code": "MINI_TEST(\"NurbsSurfaceTrimmed\", \"Constructor Planar\") {\n        // uncomment #include \"nurbssurface_trimmed.h\"\n        // uncomment #include \"nurbscurve.h\"\n        // uncomment #include \"point.h\"\n\n        // Planar curve boundary\n        std::vector<Point> pts = {\n            Point(0, 0, 0),\n            Point(3, 1, 0),\n            Point(5, 0.5, 0),\n            Point(6, 3, 0),\n            Point(4, 5, 0),\n            Point(1, 4, 0),\n        };\n        NurbsCurve bnd = NurbsCurve::create(true, 3, pts);\n        NurbsSurfaceTrimmed ts = NurbsSurfaceTrimmed::create_planar(bnd);\n\n        // Rotated planar\n        pts = {\n            Point(0, 0, 0),\n            Point(3, 1, -2),\n            Point(5, 2, -3),\n            Point(4, 4, 0),\n            Point(1, 3, 2),\n        };\n        bnd = NurbsCurve::create(true, 3, pts);\n        ts = NurbsSurfaceTrimmed::create_planar(bnd);\n\n        // Triangle\n        bnd = NurbsCurve::create(true, 1, {\n            Point(0, 0, 0),\n            Point(6, 3, 3),\n            Point(2, 5, 1),\n        });\n        ts = NurbsSurfaceTrimmed::create_planar(bnd);\n\n        // Trapezoid\n        bnd = NurbsCurve::create(true, 1, {\n            Point(0, 0, 6),\n            Point(5, 0, 6),\n            Point(4, 4, 2),\n            Point(1, 4, 2),\n        });\n        ts = NurbsSurfaceTrimmed::create_planar(bnd);\n\n        // Rectangle with a hole\n        bnd = NurbsCurve::create(true, 1, {\n            Point(0, 0, 0),\n            Point(6, 0, 0),\n            Point(6, 6, 0),\n            Point(0, 6, 0),\n        });\n        ts = NurbsSurfaceTrimmed::create_planar(bnd);\n        ts.add_hole(NurbsCurve::create(true, 1, {\n            Point(2, 2, 0),\n            Point(4, 2, 0),\n            Point(4, 4, 0),\n            Point(2, 4, 0),\n        }));\n\n        // Hexagon with 2 holes\n        double R = 4.0;\n        pts = {};\n        for (int k = 0; k < 6; ++k) {\n            double a = k * Tolerance::PI / 3.0;\n            pts.push_back(Point(R*cos(a), R*sin(a), R*cos(a)*0.5));\n        }\n        bnd = NurbsCurve::create(true, 1, pts);\n        ts = NurbsSurfaceTrimmed::create_planar(bnd);\n        ts.add_holes({\n            NurbsCurve::create(true, 1, {\n                Point(1.5, 0.5, 0.75),\n                Point(2.5, 0.5, 1.25),\n                Point(2.0, 1.5, 1.0),\n            }),\n            NurbsCurve::create(true, 1, {\n                Point(-2, -0.5, -1),\n                Point(-1, -0.5, -0.5),\n                Point(-1, -1.5, -0.5),\n                Point(-2, -1.5, -1),\n            }),\n        });\n    }",
